-- ADAM2 PostgreSQL schema v10(重構版,2026-10-28)
-- 6 張資料表。編號為整數;編號前綴可由查詢產生,例如 'ADAM2_' || lpad(adam_id::text, 6, '0'),只記錄與抗菌肽有關的資料。
CREATE TABLE molecules (
  "molecule_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "sequence" TEXT NOT NULL,
  "length" INTEGER GENERATED ALWAYS AS (char_length(sequence)) STORED,
  "n_terminus" TEXT,
  "c_terminus" TEXT,
  "stereo" TEXT,
  "linear_cyclic" TEXT,
  "molecular_weight" DOUBLE PRECISION,
  "synthesis_type" TEXT,
  "assembly_type" TEXT,
  "structure" TEXT,
  "structure_description" TEXT,
  "special_type" TEXT
);
CREATE TABLE peptide_records (
  "adam_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "molecule_id" INTEGER NOT NULL REFERENCES molecules(molecule_id),
  "peptide_name" TEXT,
  "evidence_level" TEXT,
  "source_organism" TEXT,
  "taxon" TEXT,
  "other_modifications" TEXT,
  "stereo_note" TEXT,
  "protein_family" TEXT,
  "gene" TEXT,
  "protein_existence" TEXT,
  "comments" TEXT,
  "patent_id" TEXT,
  "source_dbs" TEXT,
  "activities" TEXT,
  "uniprot_ids" TEXT,
  "pdb_ids" TEXT
);
CREATE TABLE publications (
  "publication_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "pmid" BIGINT UNIQUE,
  "title" TEXT,
  "authors" TEXT,
  "reference" TEXT
);
-- 來源原文:各資料庫對實驗的原始文字描述,與 bioactivities 的數值對照
CREATE TABLE source_texts (
  "adam_id" INTEGER PRIMARY KEY REFERENCES peptide_records(adam_id),
  "target_organism" TEXT,
  "target_group" TEXT,
  "target_object" TEXT,
  "binding_target" TEXT,
  "assay_information" TEXT,
  "hemolytic_activity" TEXT,
  "cytotoxicity" TEXT,
  "half_life" TEXT
);
CREATE TABLE bioactivities (
  "bioactivity_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "adam_id" INTEGER NOT NULL REFERENCES peptide_records(adam_id),
  "source_field" TEXT,
  "assay_metric" TEXT,
  "activity_type" TEXT,
  "target" TEXT,
  "operator" TEXT,
  "value" DOUBLE PRECISION,
  "value_max" DOUBLE PRECISION,
  "value_error" DOUBLE PRECISION,
  "unit" TEXT,
  "test_conc" DOUBLE PRECISION,
  "test_conc_unit" TEXT,
  "raw_text" TEXT,
  "value_flag" TEXT
);
-- 記錄 ↔ 論文(多對多)
CREATE TABLE record_publications (adam_id INTEGER REFERENCES peptide_records(adam_id), publication_id INTEGER REFERENCES publications(publication_id), PRIMARY KEY (adam_id, publication_id));
CREATE INDEX ON peptide_records (molecule_id);
CREATE INDEX ON peptide_records (evidence_level);
CREATE INDEX ON molecules (sequence);
CREATE INDEX ON bioactivities (adam_id);
CREATE INDEX ON bioactivities (assay_metric);
CREATE INDEX ON record_publications (publication_id);
